import { sql } from "drizzle-orm";
import { check, customType, timestamp, uuid, type AnyPgColumn } from "drizzle-orm/pg-core";

// Shared column shapes from the "Conventions" section of DATA_MODEL.md.
// Property names are camelCase; drizzle's casing option writes snake_case.

// Primary keys are UUIDv7 generated by the app (src/lib/uuid.ts), never by the database.
export const id = () => uuid().primaryKey();

export const timestamptz = () => timestamp({ withTimezone: true });

export const createdAt = () => timestamptz().notNull().defaultNow();

export const updatedAt = () =>
  timestamptz()
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date());

export const bytea = customType<{ data: Uint8Array; driverData: Uint8Array }>({
  dataType: () => "bytea",
});

// Only valid US numbers in E.164 can be stored (the "phone_us" column type in the doc).
export const PHONE_US_PATTERN = "^\\+1[2-9][0-9]{2}[2-9][0-9]{6}$";

export const phoneUsCheck = (name: string, column: AnyPgColumn) =>
  check(name, sql`${column} ~ ${sql.raw(`'${PHONE_US_PATTERN}'`)}`);

// Entry codes: 6 to 8 characters of uppercase Crockford base32 (no I, L, O or U).
export const ENTRY_CODE_PATTERN = "^[0-9A-HJKMNP-TV-Z]{6,8}$";
